const fs=require('fs'),path=require('path'),cp=require('child_process');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/pages/flow-page-contract.css',SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB;
const PAGES=[
  {page:'ajuda.html',id:'ajuda',foundation:'assets/css/pages/ajuda-foundation.css',intro:'.help-center__intro',h1:'.help-center__intro h1',p:'.help-center__intro p',mobileHero:true},
  {page:'anunciar-servico.html',id:'anunciar-servico',foundation:'assets/css/pages/anunciar-servico-foundation.css',intro:'.post-service-intro',h1:'.post-service-intro h1',p:'.post-service-intro p',mobileHero:true},
  {page:'avaliacao-profissional.html',id:'avaliacao-profissional',foundation:'assets/css/pages/avaliacao-profissional-foundation.css'},
  {page:'novidades.html',id:'novidades',foundation:'assets/css/pages/novidades-foundation.css',intro:'.news-page__intro',h1:'.news-page__intro h1',p:'.news-page__intro p',mobileHero:true},
  {page:'orcamento.html',id:'orcamento',foundation:'assets/css/pages/orcamento-foundation.css',intro:'.budget-intro',h1:'.budget-intro h1',p:'.budget-intro p',mobileHero:true},
  {page:'pagamento-profissional.html',id:'pagamento-profissional',foundation:'assets/css/pages/pagamento-profissional-foundation.css'},
  {page:'tornar-profissional.html',id:'tornar-profissional',foundation:'assets/css/pages/tornar-profissional-foundation.css',intro:'.become-pro-intro',h1:'.become-pro-intro h1',p:'.become-pro-intro p',mobileHero:true},
  {page:'verificacao-profissional.html',id:'verificacao-profissional',foundation:'assets/css/pages/verificacao-profissional-foundation.css',intro:'.professional-verification-intro',h1:'.professional-verification-intro h1',p:'.professional-verification-intro p',mobileHero:false}
];
const VIEWPORTS=[359,430,759,760,761,1023,1024,1280,1440];
const sh=c=>cp.execSync(c,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim(),assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v)}return out}
function verifyReach(){const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8')),tracked=new Set(sh('git ls-files -z assets/css').split('\0').filter(f=>f.endsWith('.css'))),expectedImporters=PAGES.map(p=>p.foundation).sort(),direct=[...tracked].filter(f=>importsFor(f,tracked).includes(TARGET)).sort();assert(JSON.stringify(direct)===JSON.stringify(expectedImporters),`direct importer drift ${JSON.stringify(direct)}`);for(const p of PAGES)assert(importsFor(p.foundation,tracked).includes(TARGET),`${p.page} foundation target drift`);const reached=[];for(const p of report.pageAssets){const seen=new Set(),todo=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(todo.length){const f=todo.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break}for(const n of importsFor(f,tracked))todo.push(n)}if(hit)reached.push(p.page)}const expectedPages=PAGES.map(p=>p.page).sort();assert(JSON.stringify(reached.sort())===JSON.stringify(expectedPages),`active reach drift ${JSON.stringify(reached)}`);console.log(`STATIC REACH PASS|pages=${reached.sort().join(',')}|directImporters=${direct.join(',')}|target=${TARGET}|affectedFamilies=6`)}
function verifyDead(p){const expected='31,32,100,124,125,126,127,128,139,140,141,142,143,144,155,179,180';assert(p.declarations.length===76&&p.dead.length===17,`parse drift ${p.declarations.length}/${p.dead.length}`);assert(p.dead.map(d=>d.line).join(',')===expected,'dead line drift');assert(new Set(p.dead.map(d=>d.selector)).size===6,'family drift');let global=0,mobile=0;for(const d of p.dead){if(!d.context)global++;else if(d.context==='@media (max-width: 760px)')mobile++;else throw new Error(`unexpected context ${d.context}`);assert(d.winnerLine>d.line&&!d.important&&!d.winnerImportant,`cascade drift ${d.line}`)}const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(global===16&&mobile===1&&identical===9&&p.dead.length-identical===8,`counts drift ${global}/${mobile}/${identical}`);console.log(`DEAD ROWS PASS|decl=76|dead=17|families=6|identical=9|changed=8|contexts=global16,mobile760=1|lines=${expected}`)}
function removeDead(p){const src=fs.readFileSync(TARGET,'utf8'),nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(`${d.property}:`),`line mismatch ${d.line}`);lines.splice(d.line-1,1)}fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/),after=parse(fs.readFileSync(TARGET,'utf8'));assert(stat[0]==='0'&&stat[1]==='17'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);assert(after.declarations.length===59&&after.dead.length===0,`after drift ${after.declarations.length}/${after.dead.length}`);console.log('EPHEMERAL DELTA PASS|file=flow-page-contract.css|additions=0|deletions=17|decl=76->59|dead=17->0')}
async function prepare(page,spec){await page.evaluate(({id})=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');if(document.body.dataset.page!==id)throw new Error(`data-page drift ${document.body.dataset.page} != ${id}`);if(!document.body.classList.contains('has-global-header'))throw new Error('missing has-global-header')},{id:spec.id})}
async function captureOne(page,spec,width){return page.evaluate(({spec,width})=>{const round=n=>Math.round(n*1000)/1000,pick=sel=>{const el=document.querySelector(sel);if(!el)return null;const s=getComputedStyle(el),r=el.getBoundingClientRect();return{display:s.display,overflowX:s.overflowX,overflowY:s.overflowY,height:s.height,minHeight:s.minHeight,maxHeight:s.maxHeight,blockSize:s.blockSize,minBlockSize:s.minBlockSize,maxBlockSize:s.maxBlockSize,scrollbarGutter:s.scrollbarGutter,fontSize:s.fontSize,lineHeight:s.lineHeight,letterSpacing:s.letterSpacing,fontWeight:s.fontWeight,color:s.color,textTransform:s.textTransform,maxWidth:s.maxWidth,rect:[round(r.x),round(r.y),round(r.width),round(r.height)],scroll:[el.scrollWidth,el.scrollHeight,el.clientWidth,el.clientHeight]}};const html=getComputedStyle(document.documentElement),body=getComputedStyle(document.body);const hr=spec.h1?pick(spec.h1):null,pr=spec.p?pick(spec.p):null,ir=spec.intro?pick(spec.intro):null;return{page:spec.page,width,root:{overflowX:html.overflowX,overflowY:html.overflowY,height:html.height,minHeight:html.minHeight,maxHeight:html.maxHeight,blockSize:html.blockSize,minBlockSize:html.minBlockSize,maxBlockSize:html.maxBlockSize,scrollbarGutter:html.scrollbarGutter},body:{overflowX:body.overflowX,overflowY:body.overflowY,height:body.height,minHeight:body.minHeight,maxHeight:body.maxHeight,overscrollBehaviorY:body.overscrollBehaviorY,webkitOverflowScrolling:body.getPropertyValue('-webkit-overflow-scrolling')},app:pick('.app-shell'),pageShell:pick('.app-shell > .page, body > .app-shell > .page'),content:pick('.page__content'),inner:pick('.page__content-inner'),intro:ir,h1:hr,p:pr,doc:{clientWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,clientHeight:document.documentElement.clientHeight,scrollHeight:document.documentElement.scrollHeight,bodyScrollWidth:document.body.scrollWidth,bodyScrollHeight:document.body.scrollHeight}}},{spec,width})}
function verifyCoverage(snaps){const vals=Object.values(snaps);assert(vals.length===PAGES.length*VIEWPORTS.length,`sample drift ${vals.length}`);assert(vals.every(s=>s.app&&s.pageShell),'shell coverage drift');for(const p of PAGES){const ps=vals.filter(s=>s.page===p.page);assert(ps.length===VIEWPORTS.length,`page coverage ${p.page}`);if(p.h1){assert(ps.every(s=>s.intro&&s.h1&&s.p),`hero coverage ${p.page}`)}}const mobileHeroPages=PAGES.filter(p=>p.mobileHero).map(p=>p.page).sort();assert(mobileHeroPages.length===5,'mobile hero family drift');console.log(`RUNTIME FAMILY COVERAGE PASS|families=6/6|pages=8|heroPages=6|mobileHeroPages=${mobileHeroPages.join(',')}`)}
async function capture(browser,tag){const out={};let n=0;for(const spec of PAGES)for(const width of VIEWPORTS){const ctx=await browser.newContext({viewport:{width,height:1000},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort()});await page.goto(`http://127.0.0.1:4173/${spec.page}?ux048-${tag}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});await prepare(page,spec);await page.waitForTimeout(30);const snap=await captureOne(page,spec,width);assert(snap.doc.scrollWidth<=snap.doc.clientWidth+1,`horizontal overflow ${tag} ${spec.page} ${width} ${JSON.stringify(snap.doc)}`);out[`${spec.page}:${width}`]=snap;n++;await ctx.close()}verifyCoverage(out);console.log(`RUNTIME CAPTURE|tag=${tag}|pages=8|viewports=${VIEWPORTS.join(',')}|samples=${n}|overflow=0`);return out}
(async()=>{assert(SHA&&BLOB,'missing env');assert(sh('git rev-parse HEAD')===SHA,'wrong HEAD');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');verifyReach();const parsed=parse(fs.readFileSync(TARGET,'utf8'));verifyDead(parsed);const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');console.log(`CASCADE RUNTIME PARITY PASS|runtimeDiffs=0|overflow=0|families=6/6|reachPages=8|viewports=${VIEWPORTS.length}|beforeSamples=${Object.keys(before).length}|afterSamples=${Object.keys(after).length}|boundary=759/760/761|staticCascadeRows=17|identicalWinners=9|changedWinners=8`)}finally{await browser.close()}}finally{server.kill('SIGTERM')}sh(`git reset --hard ${SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===SHA&&sh(`git hash-object ${TARGET}`)===BLOB&&sh('git status --porcelain')==='','restore drift');console.log(`CHECKPOINT PASS|sha=${SHA}|productMutation=0|issueCreated=0|prCreated=0`)})().catch(e=>{console.error(e.stack||e);process.exit(1)});
